+  const transcript=['threshold-decrypt-cds-or-v1',ctx.electionId,encodePoint(G),encodePoint(decodePoint(Y)),encodePoint(decodePoint(ballot.c1Hex)),encodePoint(decodePoint(ballot.c2Hex)),...branches.flatMap(b=>[encodePoint(decodePoint(b.aHex)),encodePoint(decodePoint(b.bHex))])];
